import bindAll from 'lodash.bindall';
import PropTypes from 'prop-types';
import React from 'react';
import {connect} from 'react-redux';
import {projectTitleInitialState, setProjectTitle} from '../reducers/project-title';
import downloadBlob from '../lib/download-blob';
import {setProjectUnchanged} from '../reducers/project-changed';
import {showStandardAlert, showAlertWithTimeout} from '../reducers/alerts';
import {setFileHandle} from '../reducers/tw';
import {getIsShowingProject} from '../reducers/project-state';
import log from '../lib/log';

// from sb-file-uploader-hoc.jsx
const getProjectTitleFromFilename = fileInputFilename => {
    if (!fileInputFilename) return '';

    // Accept any file extension.
    const matches = fileInputFilename.match(/^(.*)\.[^.]+$/i);

    if (!matches) return '';

    return matches[1].substring(0, 100);
};

/**
 * @param {Uint8Array[]} arrays List of byte arrays
 * @returns {number} Total length of the arrays
 */
const getLengthOfByteArrays = arrays => {
    let length = 0;
    for (let i = 0; i < arrays.length; i++) {
        length += arrays[i].byteLength;
    }
    return length;
};

/**
 * @param {Uint8Array[]} arrays List of byte arrays
 * @returns {Uint8Array} One big array containing all of the little arrays in order.
 */
const concatenateByteArrays = arrays => {
    const totalLength = getLengthOfByteArrays(arrays);
    const newArray = new Uint8Array(totalLength);
    let p = 0;
    for (let i = 0; i < arrays.length; i++) {
        newArray.set(arrays[i], p);
        p += arrays[i].byteLength;
    }
    return newArray;
};

/**
 * Check whether the HTML file picker setting is enabled.
 */
const useHtmlFilePicker = () => {
    try {
        return localStorage.getItem('potentiamod:htmlpicker') === 'true';
    } catch (err) {
        return false;
    }
};

/**
 * PotentiaMod Project saver component passes a downloadProject function to its child.
 */
class SB3Downloader extends React.Component {
    constructor (props) {
        super(props);
        bindAll(this, [
            'downloadProject',
            'saveAsNew',
            'saveToLastFile',
            'saveToLastFileOrNew'
        ]);
    }

    startedSaving () {
        this.props.onShowSavingAlert();
    }

    finishedSaving () {
        this.props.onProjectUnchanged();
        this.props.onShowSaveSuccessAlert();
        if (this.props.onSaveFinished) {
            this.props.onSaveFinished();
        }
    }

    downloadProject () {
        if (!this.props.canSaveProject) {
            return;
        }

        this.startedSaving();

        this.props.saveProjectSb3().then(content => {
            this.finishedSaving();
            downloadBlob(this.props.projectFilename, content);
        }).catch(error => {
            this.handleSaveError(error);
        });
    }

    async saveAsNew () {
        if (!this.props.canSaveProject) {
            return;
        }

        // Use the regular download when HTML picker mode is enabled.
        if (useHtmlFilePicker() || !this.props.showSaveFilePicker) {
            this.downloadProject();
            return;
        }

        try {
            const fileType = getPreferredFileType();
			
			const fileTypeDescriptions = {
                pot: 'PotentiaMod Project',
                mwp: 'MistWarp Project',
                rj: 'RemixWarp Project',
                cmp: 'CattyMod Project',
                tbp: 'ThunderBlocks Project',
                dbp: 'DashBlocks Project',
                torch: 'CodeTorch Project',
                sb3: 'Scratch Project',
                sbx: 'ScratchX Project',
                pmp: 'PenguinMod Project',
                cw: 'Cattiest World Project',
                dino: 'DinosaurMod Project',
                ich: 'Itch Project',
                bm: 'BananaMod Project',
                arkide: 'Ark IDE Project',
                zinc: 'Zinc Coding Project',
                falcon: 'FalconMod Project',
                coffee: 'Espresso Project',
                snail: 'Snail IDE Project',
                electra: 'ElectraMod Project',
                gaia: 'GaiaMod Project',
                zip: 'Generic Project'
            };

            const handle = await this.props.showSaveFilePicker({
                suggestedName: this.props.projectFilename,
                types: [
                    {
                        description: fileTypeDescriptions[fileType] || 'Custom Project',
                        accept: {
                            'application/octet-stream': [
                                `.${fileType}`
                            ]
                        }
                    }
                ],
                // Allow all file types.
                excludeAcceptAllOption: false
            });

            await this.saveToHandle(handle);
            this.props.onSetFileHandle(handle);

            const title = getProjectTitleFromFilename(handle.name);

            if (title) {
                this.props.onSetProjectTitle(title);
            }
        } catch (e) {
            this.handleSaveError(e);
        }
    }

    async saveToLastFile () {
        // Existing file handles are only usable with the File System Access API.
        if (useHtmlFilePicker() || !this.props.showSaveFilePicker) {
            this.downloadProject();
            return;
        }

        try {
            await this.saveToHandle(this.props.fileHandle);
        } catch (e) {
            this.handleSaveError(e);
        }
    }

    saveToLastFileOrNew () {
        if (useHtmlFilePicker() || !this.props.showSaveFilePicker) {
            return this.downloadProject();
        }

        if (this.props.fileHandle) {
            return this.saveToLastFile();
        }

        return this.saveAsNew();
    }

    async saveToHandle (handle) {
        if (!this.props.canSaveProject) {
            return;
        }

        if (!handle) {
            throw new Error('No file handle is available.');
        }

        let writable = null;

        try {
            let permission = await handle.queryPermission({
                mode: 'readwrite'
            });

            if (permission !== 'granted') {
                permission = await handle.requestPermission({
                    mode: 'readwrite'
                });
            }

            if (permission !== 'granted') {
                throw new Error('Write permission was not granted.');
            }

            writable = await handle.createWritable();

            this.startedSaving();

            const jszipStream = this.props.saveProjectSb3Stream();
            const abortController = new AbortController();

            jszipStream.on('error', error => {
                abortController.abort(error);
            });

            let jszipStreamRunning = false;

            const pauseJSZipStream = () => {
                if (jszipStreamRunning) {
                    jszipStreamRunning = false;
                    jszipStream.pause();
                }
            };

            const resumeJSZipStream = () => {
                if (!jszipStreamRunning) {
                    jszipStreamRunning = true;
                    jszipStream.resume();
                }
            };

            const HIGH_WATER_MARK_BYTES = 1024 * 1024 * 5;
            const WRITE_BUFFER_TARGET_SIZE_BYTES = 1024 * 1024;

            const zipStream = new ReadableStream({
                start: controller => {
                    jszipStream.on('data', data => {
                        controller.enqueue(data);

                        if (controller.desiredSize <= 0) {
                            pauseJSZipStream();
                        }
                    });

                    jszipStream.on('end', () => {
                        controller.close();
                    });

                    jszipStream.on('error', error => {
                        controller.error(error);
                    });

                    resumeJSZipStream();
                },

                pull: () => {
                    resumeJSZipStream();
                },

                cancel: () => {
                    pauseJSZipStream();
                }
            }, new ByteLengthQueuingStrategy({
                highWaterMark: HIGH_WATER_MARK_BYTES
            }));

            const queuedChunks = [];

            const fileStream = new WritableStream({
                write: async chunk => {
                    queuedChunks.push(chunk);

                    const currentSize = getLengthOfByteArrays(queuedChunks);

                    if (currentSize >= WRITE_BUFFER_TARGET_SIZE_BYTES) {
                        const newBuffer = concatenateByteArrays(queuedChunks);
                        queuedChunks.length = 0;

                        await writable.write(newBuffer);
                    }
                },

                close: async () => {
                    const lastBuffer = concatenateByteArrays(queuedChunks);

                    if (lastBuffer.byteLength > 0) {
                        await writable.write(lastBuffer);
                    }

                    await writable.close();
                    writable = null;
                },

                abort: async reason => {
                    if (writable) {
                        await writable.abort(reason);
                        writable = null;
                    }
                }
            });

            await zipStream.pipeTo(fileStream, {
                signal: abortController.signal
            });

            this.finishedSaving();
        } catch (error) {
            if (writable) {
                try {
                    await writable.abort(error);
                } catch (abortError) {
                    log.error(abortError);
                }
            }

            throw error;
        }
    }

    handleSaveError (e) {
        if (e && e.name === 'AbortError') {
            return;
        }

        log.error(e);
        this.props.onShowSaveErrorAlert();
    }

    render () {
        const {
            children
        } = this.props;

        // HTML picker mode uses regular downloads instead.
        const useHtmlPicker = useHtmlFilePicker();
        const hasNativePicker = Boolean(this.props.showSaveFilePicker);

        return children(
            this.props.className,
            this.downloadProject,
            !useHtmlPicker && hasNativePicker ? {
                available: true,
                name: this.props.fileHandle ? this.props.fileHandle.name : null,
                saveAsNew: this.saveAsNew,
                saveToLastFile: this.saveToLastFile,
                saveToLastFileOrNew: this.saveToLastFileOrNew,
                smartSave: this.saveToLastFileOrNew
            } : {
                available: false,
                smartSave: this.downloadProject
            }
        );
    }
}

const getPreferredFileType = () => {
    const validTypes = ['pot', 'cmp', 'mwp', 'rj', 'tbp', 'dbp', 'torch', 'pmp', 'cw', 'dino', 'ich', 'bm', 'arkide',
	                    'zinc', 'falcon', 'coffee', 'snail', 'electra', 'gaia', 'sbx', 'sb3', 'zip'];
	 try {
        const savedType = localStorage.getItem('potentiamod:saveFileType');
        return savedType || 'pot';
    } catch (err) {
        return 'pot';
    }
};

const getProjectFilename = (curTitle, defaultTitle) => {
    let filenameTitle = curTitle;

    if (!filenameTitle || filenameTitle.length === 0) {
        filenameTitle = defaultTitle;
    }

    const fileType = getPreferredFileType();

    // Remove any existing file extension.
    filenameTitle = filenameTitle.replace(
        /\.[^.]+$/i,
        ''
    );

    return `${filenameTitle.substring(0, 100)}.${fileType}`;
};

SB3Downloader.propTypes = {
    children: PropTypes.func,
    className: PropTypes.string,
    fileHandle: PropTypes.shape({
        name: PropTypes.string
    }),
    onSaveFinished: PropTypes.func,
    projectFilename: PropTypes.string,
    saveProjectSb3: PropTypes.func,
    saveProjectSb3Stream: PropTypes.func,
    canSaveProject: PropTypes.bool,
    onSetFileHandle: PropTypes.func,
    onSetProjectTitle: PropTypes.func,
    onShowSavingAlert: PropTypes.func,
    onShowSaveSuccessAlert: PropTypes.func,
    onShowSaveErrorAlert: PropTypes.func,
    onProjectUnchanged: PropTypes.func,
    showSaveFilePicker: PropTypes.func
};

SB3Downloader.defaultProps = {
    className: '',
    showSaveFilePicker:
        typeof window !== 'undefined' &&
        typeof window.showSaveFilePicker === 'function' &&
        !navigator.userAgent.includes('Android') ?
            window.showSaveFilePicker.bind(window) :
            null
};

const mapStateToProps = state => ({
    fileHandle: state.scratchGui.tw.fileHandle,
    saveProjectSb3: state.scratchGui.vm.saveProjectSb3.bind(state.scratchGui.vm),
    saveProjectSb3Stream: state.scratchGui.vm.saveProjectSb3Stream.bind(state.scratchGui.vm),
    canSaveProject: getIsShowingProject(state.scratchGui.projectState.loadingState),
    projectFilename: getProjectFilename(state.scratchGui.projectTitle, projectTitleInitialState)
});

const mapDispatchToProps = dispatch => ({
    onSetFileHandle: fileHandle => dispatch(setFileHandle(fileHandle)),
    onSetProjectTitle: title => dispatch(setProjectTitle(title)),
    onShowSavingAlert: () => showAlertWithTimeout(dispatch, 'saving'),
    onShowSaveSuccessAlert: () => showAlertWithTimeout(dispatch, 'twSaveToDiskSuccess'),
    onShowSaveErrorAlert: () => dispatch(showStandardAlert('savingError')),
    onProjectUnchanged: () => dispatch(setProjectUnchanged())
});

export default connect(
    mapStateToProps,
    mapDispatchToProps
)(SB3Downloader);